function createTableHTML(n,t){let e="";for(const[t,a]of Object.entries(n))e+=`\n      <tr>\n        <td><code>${escapeHTML(t)}</code></td>\n        <td class="wingdings-char">${escapeHTML(a)}</td>\n      </tr>\n    `;return`\n    <table class="mapping-table">\n      <thead>\n        <tr>\n          <th>${t("モジ (ASCII)")}</th>\n          <th>${t("キゴウ (WINGDINGS)")}</th>\n        </tr>\n      </thead>\n      <tbody>\n        ${e}\n      </tbody>\n    </table>\n  `}function escapeHTML(n){const t=document.createElement("p");return t.textContent=n,t.innerHTML}document.addEventListener("DOMContentLoaded",async()=>{const n=document.getElementById("mapping-table-container");function t(n){return n.replace(/[\u3040-\u309F]/g,function(n){const t=n.charCodeAt(0)+96;return String.fromCharCode(t)})}try{const e=await fetch("../data/wingdings-map.json");if(!e.ok)throw new Error(`HTTP error! status: ${e.status}`);const a=(await e.json()).ascii_to_wingdings;if(!a)throw new Error("Mapping data not found in JSON file.");n.innerHTML=createTableHTML(a,t)}catch(e){n.innerHTML=`<p class="error">${t("タイオウヒョウノヨミコミニシッパイシマシタ")}: ${e.message}</p>`,console.error("Failed to load mapping table:",e)}});